 async function importBook(){
  if(mode!=='reading'||importing||saving)return;
  const destination=currentFolder;
  setImporting(true);setReaderError('');
  try{
   const response=await fetch('/api/library/import',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});
   const result=await response.json() as {imported:boolean;book?:LibraryBook;error?:string};
   if(!response.ok)throw Error(result.error||'没有导入');
   if(result.imported&&result.book){
    const latest=dataRef.current;
    const folderId=destination&&(latest.libraryFolders||[]).some(folder=>folder.id===destination)?destination:undefined;
    const existing=latest.libraryBooks.find(book=>book.id===result.book!.id);
    const book:LibraryBook=existing?{...result.book,...existing,inReadingLibrary:true,...(destination!==null?{folderId}:{})}:{...result.book,folderId,inReadingLibrary:true};
    const libraryBooks=existing?latest.libraryBooks.map(item=>item.id===book.id?book:item):[...latest.libraryBooks,book];
    if(await saveRef.current({...latest,libraryBooks},existing?'已加入读书书架':'书籍已导入')){
     setSelectedFolder(destination===null?null:folderId||'');switchBook(book.id);
    }else setReaderError('书籍信息未能保存，请等当前保存完成后重新导入。');
   }
  }catch(error){setReaderError((error as Error).message);}
  finally{setImporting(false);}
 }

